"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["289"],{95719(e){e.exports=JSON.parse('{"id":"FIN-284","slug":"initial-public-offering","term":"Initial Public Offering (IPO)","also_known_as":["IPO"],"difficulty":"Intermediate","definition":"An initial public offering (IPO) is the first time a private company sells its shares to the public, after which its shares can be traded on a stock exchange.","explanation":["Companies go public through an IPO to raise money for growth, to give early investors and founders a way to sell some of their holdings and to raise their profile. Once listed, the company can more easily raise further money in the future.","The process usually involves investment banks, which help prepare detailed documents describing the business, its finances and its risks, advise on the share price and find investors. The company must meet the exchange\'s listing requirements and the rules of securities regulators.","For example, a company might sell 20 million shares at 25 each in its IPO, raising 500 million. On its first day of trading, the share price may rise above or fall below the IPO price, depending on demand.","Going public brings obligations. Listed companies must publish regular financial reports, follow governance rules and face scrutiny from investors and the media. Some companies choose to stay private to avoid these demands. IPO investments can be volatile, and newly listed shares do not always perform well in the long run."],"note":"","total":1725,"prev":{"slug":"initial-margin","term":"Initial Margin"},"next":{"slug":"inorganic-growth","term":"Inorganic Growth"}}')}}]);